import {money,registerPurchase,decide} from './domain.mjs';
const sum=a=>a.reduce((s,x)=>s+x,0),cents=x=>Math.round(Number(x)*100);
const categories=['Matéria-prima','Acessório','Componente'];
export function allocate(total,weights){let target=cents(total);if(!Number.isFinite(target)||target<0||weights.some(x=>!Number.isFinite(x)||x<0))throw Error('Rateio inválido');let base=sum(weights);if(!weights.length||(!base&&target))throw Error('Não há base para rateio');let exact=weights.map(w=>base?target*w/base:0),parts=exact.map(Math.floor),order=exact.map((x,i)=>({i,r:x-parts[i]})).sort((a,b)=>b.r-a.r||a.i-b.i);for(let n=target-sum(parts),i=0;i<n;i++)parts[order[i%order.length].i]++;return parts.map(x=>x/100)}
export function parseNfe(xml,Parser=globalThis.DOMParser){
 if(typeof xml!=='string'||!xml.trim())throw Error('XML vazio');if(/<!DOCTYPE|<!ENTITY/i.test(xml))throw Error('XML com declaração de entidades não é aceito');
 let failed=false,d;try{d=new Parser({errorHandler:{warning:()=>{failed=true},error:()=>{failed=true},fatalError:()=>{failed=true}}}).parseFromString(xml,'application/xml')}catch{throw Error('XML inválido')}
 if(failed||!d||d.getElementsByTagName('parsererror').length||d.getElementsByTagNameNS('*','parsererror').length)throw Error('XML inválido');
 const nodes=(n,t)=>n?Array.from(n.getElementsByTagNameNS('*',t)):[],first=(n,t)=>nodes(n,t)[0],get=(n,t)=>first(n,t)?.textContent||'',num=(n,t)=>{let raw=get(n,t);if(!raw)return 0;let v=Number(raw);if(!Number.isFinite(v)||v<0)throw Error('Valor inválido no XML: '+t);return v};
 let inf=first(d,'infNFe');if(!inf)throw Error('XML não é NF-e');let key=inf.getAttribute('Id')?.replace(/^NFe/,'')||get(d,'chNFe');if(!/^\d{44}$/.test(key))throw Error('Chave NF-e inválida');
 let emit=first(inf,'emit'),ide=first(inf,'ide'),tot=first(first(inf,'total'),'ICMSTot');if(!emit||!tot||!first(tot,'vNF'))throw Error('Fornecedor ou total da NF-e ausente');
 const taxNames=['vICMS','vICMSDeson','vFCP','vICMSST','vFCPST','vFCPSTRet','vICMSSTRet','vIPI','vII','vPIS','vCOFINS','vIPIDevol','vTotTrib','vISSQN'];
 let items=nodes(inf,'det').map((det,i)=>{let p=first(det,'prod'),tax=first(det,'imposto');if(!p)throw Error('Item sem produto');let taxes={};for(let name of taxNames)taxes[name]=sum(nodes(tax,name).map(n=>{let v=Number(n.textContent);if(!Number.isFinite(v)||v<0)throw Error('Imposto inválido');return v}));taxes.vIPIDevol+=num(first(det,'impostoDevol'),'vIPIDevol');let qty=num(p,'qCom');if(qty<=0)throw Error('Quantidade inválida no item '+(i+1));return {line:det.getAttribute('nItem')||String(i+1),code:get(p,'cProd'),description:get(p,'xProd'),unit:get(p,'uCom'),quantity:qty,unitPrice:num(p,'vUnCom'),total:num(p,'vProd'),discount:num(p,'vDesc'),freight:num(p,'vFrete'),insurance:num(p,'vSeg'),other:num(p,'vOutro'),included:get(p,'indTot')!=='0',deductDeson:get(tax,'indDeduzDeson'),taxes,factor:1}});
 if(!items.length)throw Error('NF-e sem produtos');if(items.some(x=>!x.code||!x.description||!x.unit))throw Error('Item sem código, descrição ou unidade');
 let totals={};for(let tag of ['vProd','vDesc','vFrete','vSeg','vOutro','vICMS','vICMSDeson','vST','vFCPST','vIPI','vII','vPIS','vCOFINS','vIPIDevol','vTotTrib','vNF'])totals[tag]=num(tot,tag);
 let installments=nodes(first(inf,'cobr'),'dup').map((n,i)=>({number:get(n,'nDup')||String(i+1),due:get(n,'dVenc'),amount:num(n,'vDup')}));let payments=nodes(first(inf,'pag'),'detPag').map(n=>({method:get(n,'tPag'),amount:num(n,'vPag'),date:get(n,'dPag')}));
 let result={key,number:get(ide,'nNF'),series:get(ide,'serie'),issued:(get(ide,'dhEmi')||get(ide,'dEmi')).slice(0,10),supplier:get(emit,'xNome'),supplierDocument:get(emit,'CNPJ')||get(emit,'CPF'),supplierTradeName:get(emit,'xFant'),items,totals,total:totals.vNF,installments,payments,rawXml:xml};if(!result.supplier||!result.supplierDocument)throw Error('Fornecedor sem nome ou CNPJ/CPF');return reconcileNfe(result)
}
export function reconcileNfe(invoice){
 let n=structuredClone(invoice);n.warnings=[];let eligible=n.items.map((x,i)=>x.included===false?-1:i).filter(i=>i>=0),weights=eligible.map(i=>Math.max(0,n.items[i].total-n.items[i].discount));if(!sum(weights))weights=eligible.map(i=>n.items[i].quantity);
 for(let [field,tag] of [['freight','vFrete'],['insurance','vSeg'],['other','vOutro'],['discount','vDesc']]){let raw=eligible.map(i=>n.items[i][field]||0),total=n.totals[tag];if(cents(sum(raw))>0&&cents(sum(raw))!==cents(total))n.warnings.push('Valores de '+tag+' nos itens divergem do total destacado. Confira o XML.');let amounts=cents(sum(raw))===cents(total)?raw:allocate(total,weights);eligible.forEach((idx,j)=>{n.items[idx]['allocated'+field[0].toUpperCase()+field.slice(1)]=amounts[j]})}
 for(let [field,tag,itemTag] of [['ipi','vIPI','vIPI'],['importDuty','vII','vII'],['st','vST','vICMSST'],['fcpst','vFCPST','vFCPST'],['returnedIpi','vIPIDevol','vIPIDevol']]){let raw=eligible.map(i=>n.items[i].taxes?.[itemTag]||0);if(cents(sum(raw))>0&&cents(sum(raw))!==cents(n.totals[tag]))n.warnings.push('Imposto '+tag+' nos itens diverge do total. Confira o XML.');let amounts=cents(sum(raw))===cents(n.totals[tag])?raw:allocate(n.totals[tag],weights);eligible.forEach((idx,j)=>{n.items[idx][field]=amounts[j]})}
 let nonDeducted=sum(n.items.filter(x=>x.included!==false&&x.deductDeson==='0').map(x=>x.taxes?.vICMSDeson||0));let deduction=Math.max(0,n.totals.vICMSDeson-nonDeducted),rawDed=eligible.map(i=>n.items[i].deductDeson==='0'?0:(n.items[i].taxes?.vICMSDeson||0)),deductions=cents(sum(rawDed))===cents(deduction)?rawDed:allocate(deduction,weights);
 n.items.forEach(x=>{x.acquisitionTotal=0;x.costUnit=0});eligible.forEach((idx,j)=>{let x=n.items[idx];x.desonDeduction=deductions[j];x.acquisitionTotal=money(x.total-x.allocatedDiscount+x.allocatedFreight+x.allocatedInsurance+x.allocatedOther+x.ipi+x.importDuty+x.st+x.fcpst+x.returnedIpi-x.desonDeduction);x.costUnit=x.acquisitionTotal/x.quantity});
 n.calculatedTotal=money(sum(n.items.map(x=>x.acquisitionTotal)));n.difference=money(n.total-n.calculatedTotal);n.reconciled=cents(n.difference)===0;if(cents(sum(n.items.filter(x=>x.included!==false).map(x=>x.total)))!==cents(n.totals.vProd))n.warnings.push('A soma dos produtos diverge do total de produtos do XML.');if(!n.reconciled)n.warnings.push('Composição divergente do total da nota. Registro bloqueado para conferência.');n.reconciled=n.reconciled&&!n.warnings.length;return n
}
export function prepareInstallments(invoice,{due,amounts}={}){let rows=invoice.installments||[];if(rows.length){if(rows.some(x=>!validDate(x.due)||!Number.isFinite(x.amount)||x.amount<=0))throw Error('Duplicatas com vencimento ou valor inválido');if(cents(sum(rows.map(x=>x.amount)))!==cents(invoice.total))throw Error('Duplicatas não somam o total da nota. Confira o documento antes de registrar');return rows.map(x=>({...x,id:crypto.randomUUID(),payments:[]}))}if(!validDate(due))throw Error('XML sem vencimento: informe o vencimento confirmado');return [{id:crypto.randomUUID(),number:'1',due,amount:invoice.total,payments:[]}]}
function validDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v||''))return false;let d=new Date(v+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===v}
export function importInvoice(state,invoice,settings){
 let n=reconcileNfe(invoice);if(!n.reconciled)throw Error('Total da nota não confere: diferença '+money(n.difference));if(state.purchases.some(p=>p.key===n.key))throw Error('Nota já importada');if(!validDate(settings.received))throw Error('Data de recebimento inválida');let next=structuredClone(state),doc=n.supplierDocument.replace(/\D/g,''),supplier=next.suppliers.find(s=>String(s.document||'').replace(/\D/g,'')===doc);if(!supplier){supplier={id:crypto.randomUUID(),name:n.supplier,document:n.supplierDocument};next.suppliers.push(supplier)}else{supplier.name=n.supplier}supplier.tradeName=n.supplierTradeName;
 let items=n.items.map((x,i)=>{let setting=settings.items[i];if(!setting)throw Error('Classifique todos os itens');let selected=setting.selected!==false;let existing=next.materials.find(m=>m.id===setting.materialId)||next.materials.find(m=>m.supplier===supplier.id&&m.code===x.code);if(selected&&!categories.includes(setting.category))throw Error('Escolha a categoria do item '+x.code);let factor=Number(setting.factor);if(selected&&(!Number.isFinite(factor)||factor<=0))throw Error('Conversão inválida no item '+x.code);if(existing&&existing.buyUnit!==x.unit&&!setting.confirmConversion)throw Error('Unidade de compra mudou no item '+x.code+': confirme a conversão');if(selected&&!existing){existing={id:crypto.randomUUID(),code:x.code,description:x.description,category:setting.category,buyUnit:x.unit,unit:setting.unit?.trim()||x.unit,supplier:supplier.id,purchaseFactor:factor,cost:null,source:'XML NF-e'};next.materials.push(existing)}if(selected){existing.purchaseFactor=factor;existing.category=setting.category;existing.sourceDescription=x.description;existing.sourceUnitPrice=x.unitPrice}return {...x,recordMaterial:selected,materialId:selected?existing.id:null,factor:selected?factor:1,discount:x.allocatedDiscount||0,freight:x.allocatedFreight||0,other:(x.allocatedInsurance||0)+(x.allocatedOther||0)+(x.ipi||0)+(x.importDuty||0)+(x.st||0)+(x.fcpst||0)+(x.returnedIpi||0),deduction:x.desonDeduction||0,original:{code:x.code,description:x.description,unit:x.unit,unitPrice:x.unitPrice,discount:x.discount,freight:x.freight,insurance:x.insurance,other:x.other}}});
 let purchase={...n,id:crypto.randomUUID(),supplierId:supplier.id,origin:'XML NF-e',documentStatus:'XML conferido',approval:'pending',approveWholeInvoice:true,received:settings.received,items,installments:prepareInstallments(n,settings)};registerPurchase(next,purchase);Object.assign(state,next);return purchase
}
export function decideInvoice(state,purchaseId,approved,actor){let p=state.purchases.find(p=>p.id===purchaseId);if(!p||!p.approveWholeInvoice||p.approval!=='pending')throw Error('Nota não está pendente');if(!actor?.trim())throw Error('Informe o responsável');let candidates=state.proposals.filter(x=>x.purchaseId===p.id&&x.status==='pending');decide(state,candidates.map(x=>x.id),approved,actor,{purchaseId});p.approval=approved?'approved':'rejected';p.approvedTotal=approved?p.total:null;state.audit.push({at:new Date().toISOString(),actor,action:approved?'invoice-approved':'invoice-rejected',purchaseId:p.id,number:p.number,total:p.total,key:p.key});return state}
